mapper.select:
SELECT id, user_id, name, db_type, host, port, database_name, username, password, remark, pool_min_idle, pool_max_size, pool_idle_timeout_sec, pool_max_lifetime_sec, pool_conn_timeout_sec, create_time, update_time FROM datasource
AND name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY ${sortField} ${sortOrder}

SELECT id, user_id, name, db_type, host, port, database_name, username, password, remark, pool_min_idle, pool_max_size, pool_idle_timeout_sec, pool_max_lifetime_sec, pool_conn_timeout_sec, create_time, update_time
FROM datasource
WHERE id = #{id}

SELECT id, name FROM datasource
WHERE id IN
#{id}
